import sys
import xml.etree.ElementTree as ET
import re
from collections import defaultdict

def evaluate_formula(formula, metrics):
    try:
        # Replace metric names with their values
        for name, value in metrics.items():
            formula = re.sub(r'\b' + re.escape(name) + r'\b', str(value), formula)

        # Evaluate the expression safely
        try:
            result = eval(formula)
        except ZeroDivisionError:
            raise ValueError("division by zero")
        except Exception as e:
            raise ValueError("invalid syntax")

        return result
    except KeyError as e:
        raise ValueError(f"unknown name: {e.args[0]}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python calc_metrics.py <xml_file>", file=sys.stderr)
        sys.exit(1)

    xml_file = sys.argv[1]
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except Exception as e:
        print(f"Error parsing XML: {e}", file=sys.stderr)
        sys.exit(1)

    metrics = {}
    log_file = "run.log"

    for metric in root.findall('metric'):
        name = metric.get('name')
        formula = metric.get('formula')

        if not name or not formula:
            print(f"Invalid metric definition: missing name or formula for metric '{name}'", file=sys.stderr)
            sys.exit(1)

        try:
            value = evaluate_formula(formula, metrics)
            metrics[name] = value
            print(f"OK {name}={repr(value)}")
        except ValueError as e:
            print(f"ERROR {name}: {e}", file=sys.stderr)

    with open(log_file, 'w') as f:
        for name, value in metrics.items():
            f.write(f"OK {name}={repr(value)}\n")
        for error in sys.stderr_buffer.getvalue().decode().splitlines():
            if "ERROR" in error:
                f.write(error + "\n")

    if any("ERROR" in line for line in sys.stderr_buffer.getvalue().decode().splitlines()):
        sys.exit(1)
    else:
        sys.exit(0)

if __name__ == "__main__":
    sys.stderr_buffer = sys.stderr
    main()
